class Solution {
  public int[] countPairs(int n, int[][] edges, int[] queries) {
    int[] degree = new int[n + 1];
    java.util.Map<Long, Integer> shared = new java.util.HashMap<>();
    for (int[] e : edges) {
      degree[e[0]]++;
      degree[e[1]]++;
      int a = Math.min(e[0], e[1]), b = Math.max(e[0], e[1]);
      long key = ((long) a << 32) | b;
      shared.put(key, shared.getOrDefault(key, 0) + 1);
    }
    int[] sorted = new int[n];
    for (int i = 0; i < n; i++) sorted[i] = degree[i + 1];
    java.util.Arrays.sort(sorted);
    int[] result = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int q = queries[qi], count = 0;
      for (int i = 0; i < n; i++) {
        int lo = i + 1, hi = n - 1;
        while (lo <= hi) {
          int m = (lo + hi) >>> 1;
          if (sorted[m] + sorted[i] > q) hi = m - 1;
          else lo = m + 1;
        }
        count += n - lo;
      }
      for (java.util.Map.Entry<Long, Integer> e : shared.entrySet()) {
        int a = (int) (e.getKey() >> 32), b = (int) (long) e.getKey();
        if (degree[a] + degree[b] > q && degree[a] + degree[b] - e.getValue() <= q) count--;
      }
      result[qi] = count;
    }
    return result;
  }
}
